#include <WiFi.h>
#include <WebServer.h>
WebServer server(80);
void setup() {
  pinMode(18, OUTPUT);
  WiFi.begin("VoltNet", "pass");
  while (WiFi.status() != WL_CONNECTED) delay(50);
  server.on("/", []() {
    server.send(200, "text/html", "<h1>Smart Switch</h1><a href='/on'>Turn on</a> <a href='/off'>Turn off</a>");
  });
  server.on("/on", []() {
    digitalWrite(18, HIGH);
    server.send(200, "text/html", "<h1>Light ON</h1><a href='/off'>Turn off</a>");
  });
  server.on("/off", []() {
    digitalWrite(18, LOW);
    server.send(200, "text/html", "<h1>Light OFF</h1><a href='/on'>Turn on</a>");
  });
  server.begin();
}
void loop() { server.handleClient(); }
